/// <summary>
///     The <c>AVASalesLineBackOrderFrm_SalesLineDS_Extension</c> class is the extension for <c>SalesLineBackOrder</c>
/// </summary>
[ExtensionOf(formDataSourceStr(SalesLineBackOrder, SalesLine))]
final class AVASalesLineBackOrderFrm_SalesLineDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>active</c> method.
/// </summary>
/// <returns>
///    <c>int</c> as return value
/// </returns>
public int active()
{
    int retVal;

    FormRun                 formRun;
    FormDataSource          locDS;
    SalesTable              locSalesTable;

    FormRealControl         locFRC;

    retVal = next active();

    formRun         = this.formRun();
    locDS           = element.SalesTable_DS;
    locSalesTable   = locDS.cursor();

    if(locDS)
    {
        locSalesTable   = locDS.cursor();
        //locFRC          = element.Design().controlname(formControlStr(SalesLineBackOrder, GridInfo_GrossWeight));
        locFRC          = element.GridInfo_GrossWeight;
        locFRC.realValue(locSalesTable.avaGetGrossWeightRemaining());

        //element.GridInfo_GrossWeight = locSalesTable.avaGetGrossWeightRemaining();
    }

    return retVal;
}
